\set ON_ERROR_STOP on
-------------------------------------------------------------------
-- Part 1c: the one pre-git commit holding EUC-JP Japanese text,
-- 200506152034.j5FKYqrZ030874 (2005-06-15, rushani).  Its commit message
-- is the whole Japanese Handbook desktop chapter: FreeBSD doc commit
-- 537770631a was made with the chapter text as its message.
--
-- FreshPorts stored the EUC-JP bytes double-encoded, and Part 1's
-- run-by-run pass then turned some runs back into raw EUC-JP bytes, so
-- the stored text can no longer be decoded reliably.  This replaces it
-- with the commit message itself, taken from the FreeBSD doc repository
-- (git cat-file commit 537770631a).  In git the message is double-encoded
-- too; it was undone (UTF-8 -> Latin-1 bytes = EUC-JP), checked to be
-- valid EUC-JP, tabs expanded to 8-column stops (counting EUC-JP bytes,
-- as the stored row has spaces where git has tabs), final newline
-- dropped, and is held below as EUC-JP hex.
--
-- Safety check: the stored row and the replacement must have the same
-- ASCII text (every byte below 0x80, in order; trailing newlines ignored).
-- That proves they are the same message with only the Japanese differing.
-- Only then is the row replaced.  Needs 00-helpers.sql loaded.
-------------------------------------------------------------------
DROP TABLE IF EXISTS pg_temp.eucjp_fix;
CREATE TEMP TABLE eucjp_fix AS
SELECT convert_from(convert(decode('', 'hex'), 'EUC_JP', 'UTF8'), 'SQL_ASCII') AS fixed;

-- the check, before anything changes: expect same_ascii_text t
SELECT rtrim(regexp_replace(c.description, '[\x80-\xff]', '', 'g'), E'\n')
     = rtrim(regexp_replace(f.fixed,       '[\x80-\xff]', '', 'g'), E'\n') AS same_ascii_text,
       length(regexp_replace(c.description, '[\x80-\xff]', '', 'g'))          AS stored_ascii_bytes,
       length(regexp_replace(f.fixed,       '[\x80-\xff]', '', 'g'))          AS fixed_ascii_bytes,
       length(c.description) AS stored_bytes, length(f.fixed) AS fixed_bytes,
       substring(f.fixed FROM '<title>[^<]*</title>') AS title,
       substring(f.fixed FROM '<contrib>[^<]*</contrib>') AS contrib
  FROM commit_log c, eucjp_fix f
 WHERE c.message_id = '200506152034.j5FKYqrZ030874@repoman.freebsd.org';

BEGIN;
UPDATE commit_log C
   SET description = F.fixed
  FROM eucjp_fix F
 WHERE C.message_id = '200506152034.j5FKYqrZ030874@repoman.freebsd.org'
   AND rtrim(regexp_replace(C.description, '[\x80-\xff]', '', 'g'), E'\n')
     = rtrim(regexp_replace(F.fixed,       '[\x80-\xff]', '', 'g'), E'\n');   -- expect 1

INSERT INTO cache_clearing_ports (port_id, category, port)
SELECT DISTINCT PA.id, PA.category, PA.name
  FROM commit_log C JOIN commit_log_ports CLP ON CLP.commit_log_id = C.id
                    JOIN ports_all PA        ON PA.id = CLP.port_id
 WHERE C.message_id = '200506152034.j5FKYqrZ030874@repoman.freebsd.org'
    ON CONFLICT DO NOTHING;
NOTIFY port_updated;

-- check: valid UTF-8, no mojibake left, title reads correctly
SELECT pg_temp.bad_utf8(description)            AS bad_utf8,
       description ~ pg_temp.mojibake_re()      AS mojibake,
       substring(description FROM '<title>[^<]*</title>') AS title,
       length(description)                      AS bytes_after
  FROM commit_log
 WHERE message_id = '200506152034.j5FKYqrZ030874@repoman.freebsd.org';
-- COMMIT;  or  ROLLBACK;
